  { kind: 'interval', label: 'Interval', hint: 'every N seconds' },
  { kind: 'cron', label: 'Cron', hint: '5-field' },
];

const SIMPLE_FREQS: { freq: SimpleFreq; label: string }[] = [
  { freq: 'minutes', label: '每 N 分钟' },
